#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""独立的 DRAT 证明验证器（本任务中证明均为 RUP 追加 + 删除）。

用法：
  python3 verify.py <实例.cnf> <证明.drat>
有效打印 VALID 并以 0 退出；否则打印 INVALID 并以非 0 退出。

检查规则：
- 删除行 d <lits> 0：删除一条当前活动且完全相同（按多重集）的子句。
- 追加行 <lits> 0：该子句必须满足 RUP——先令其中所有文字为假，
  再在活动公式上做单元传播，若导出冲突则该子句成立（包含/重言式子句
  也接受）。
- 证明必须追加空子句，空子句的 RUP 即原公式（含已学子句）单元传播冲突。
仅使用标准库。
"""

import sys


def parse_dimacs(path):
    nvars = 0
    clauses = []
    cur = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line or line[0] == "c":
                continue
            if line[0] == "p":
                nvars = int(line.split()[2])
                continue
            for tok in line.split():
                x = int(tok)
                if x == 0:
                    clauses.append(cur)
                    cur = []
                else:
                    cur.append(x)
    if cur:
        clauses.append(cur)
    return nvars, clauses


def parse_proof(path):
    steps = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            deleted = False
            body = line
            if body[0] == "d":
                deleted = True
                body = body[1:].strip()
            toks = body.split()
            vals = [int(t) for t in toks]
            if vals and vals[-1] == 0:
                vals = vals[:-1]
            steps.append((deleted, vals))
    return steps


class Checker:
    def __init__(self, nvars):
        self.n = nvars
        self.active = []      # 每条活动子句一个 dict
        self.watches = {}     # 假文字 -> 子句集合
        self.value = {}

    def wkey(self, lit):
        return -lit  # 当 lit 变假时触发

    def add_clause(self, clause):
        # 重言式子句恒成立
        s = set(clause)
        if any(-x in s for x in s):
            return True
        rec = {"lits": list(clause), "alive": True}
        self.active.append(rec)
        if clause:
            for watch in clause[:2]:
                self.watches.setdefault(-watch, []).append(rec)
        return True

    def remove_clause(self, clause):
        target = sorted(clause)
        for rec in self.active:
            if rec["alive"] and sorted(rec["lits"]) == target:
                rec["alive"] = False
                return True
        return False

    def value_of(self, lit):
        v = self.value.get(abs(lit))
        if v is None:
            return 0
        return v if lit > 0 else -v

    def rup(self, clause):
        assign = {}
        trail = []
        for lit in clause:
            v = abs(lit)
            if v in assign:
                if assign[v] == (lit > 0):
                    return True  # 矛盾假设/重言式，直接成立
                continue
            assign[v] = lit > 0  # 令文字为假 => 变量取相反值
            # 令 lit 为假：变量值 = (lit<0)
            assign[v] = lit < 0
            trail.append(v)
        self.value = assign
        qhead = 0
        conflict = False
        while qhead < len(trail):
            v = trail[qhead]
            qhead += 1
            # 刚赋值的变量；其变假的文字 = 与赋值相反极性
            val = assign[v]
            false_lit = v if not val else -v
            for rec in self.watches.get(false_lit, ()):
                if not rec["alive"]:
                    continue
                unassigned = None
                has_true = False
                count_un = 0
                for lit in rec["lits"]:
                    lv = self.value_of(lit)
                    if lv == 1:
                        has_true = True
                        break
                    if lv == 0:
                        count_un += 1
                        unassigned = lit
                if has_true or count_un > 1:
                    continue
                if count_un == 1:
                    uv = abs(unassigned)
                    if uv not in assign:
                        assign[uv] = unassigned > 0
                        trail.append(uv)
                    continue
                conflict = True  # 全部文字为假
                break
            if conflict:
                break
        self.value = {}
        return conflict


def main():
    if len(sys.argv) != 3:
        print("usage: python3 verify.py <file.cnf> <proof.drat>", file=sys.stderr)
        return 2
    try:
        nvars, clauses = parse_dimacs(sys.argv[1])
        steps = parse_proof(sys.argv[2])
    except Exception as exc:
        print("INVALID")
        print("parse error: %s" % exc, file=sys.stderr)
        return 1

    checker = Checker(nvars)
    for c in clauses:
        checker.add_clause(c)

    added_empty = False
    for i, (deleted, clause) in enumerate(steps):
        if len(clause) != len(set(abs(x) for x in clause)) and clause:
            # 出现同变量重复文字不影响语义，但含 x 与 -x 视为重言式
            pass
        if deleted:
            if not checker.remove_clause(clause):
                print("INVALID")
                print("step %d: deletion of absent clause %s" % (i + 1, clause),
                      file=sys.stderr)
                return 1
            continue
        if not checker.rup(clause):
            print("INVALID")
            print("step %d: clause %s is not RUP" % (i + 1, clause),
                  file=sys.stderr)
            return 1
        checker.add_clause(clause)
        if not clause:
            added_empty = True

    if not added_empty:
        print("INVALID")
        print("proof does not derive the empty clause", file=sys.stderr)
        return 1
    print("VALID")
    return 0


if __name__ == "__main__":
    sys.exit(main())
